 a.is_active,\n    b.currency,\n    b.opening_id,\n    b.opening_as_of,\n    b.opening_amount::numeric(14,2) AS opening_amount,\n    b.system_balance,\n    b.inflow,\n    b.outflow\n   FROM finance_treasury_accounts a\n     CROSS JOIN LATERAL expense_account_balance(a.bank_account_id, a.cash_location_id) b(currency, opening_id, opening_as_of, opening_amount, system_balance, inflow, outflow);"},"finance_payment_effective_invoice_allocations":{"options":["security_invoker=true"],"definition":" WITH allocation_legs AS (\n         SELECT allocation.payment_id,\n            allocation.invoice_id,\n            allocation.cash_allocated::numeric AS cash_delta,\n            allocation.wht_credit_allocated::numeric AS wht_delta\n           FROM finance_payment_invoice_allocations allocation\n        UNION ALL\n         SELECT reallocation.payment_id,\n            reallocation.source_invoice_id,\n            - reallocation.cash_moved::numeric,\n            - reallocation.wht_moved::numeric\n           FROM finance_payment_allocation_reallocations reallocation\n        UNION ALL\n         SELECT reallocation.payment_id,\n            reallocation.target_invoice_id,\n            reallocation.cash_moved::numeric AS cash_moved,\n            reallocation.wht_moved::numeric AS wht_moved\n           FROM finance_payment_allocation_reallocations reallocation\n        ), effective AS (\n         SELECT allocation_legs.payment_id,\n            allocation_legs.invoice_id,\n            sum(allocation_legs.cash_delta)::numeric(14,2) AS effective_cash_allocated,\n            sum(allocation_legs.wht_delta)::numeric(14,2) AS effective_wht_credit_allocated\n           FROM allocation_legs\n          GROUP BY allocation_legs.payment_id, allocation_legs.invoice_id\n        )\n SELECT payment_id,\n    invoice_id,\n    effective_cash_allocated,\n    effective_wht_credit_allocated,\n    (effective_cash_allocated + effective_wht_credit_allocated)::numeric(14,2) AS effective_settlement_total\n   FROM effective\n  WHERE effective_cash_allocated <> 0::numeric OR effective_wht_credit_allocated <> 0::numeric;"}}}'::jsonb||jsonb_build_object('rows',baseline->'rows');
